package com.italiano2774.nativeapp;
import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.fragment.app.Fragment;import java.util.*;
public class WritingFragment extends Fragment{
 private List<WritingPrompt> items;private int index=0;private ProgressStore progress;private TextView level,title,prompt,tip,result,reference,status;private EditText answer;
 @Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){View v=i.inflate(R.layout.fragment_writing,c,false);progress=new ProgressStore(requireContext());items=WritingRepository.get(requireContext()).all();level=v.findViewById(R.id.text_writing_level);title=v.findViewById(R.id.text_writing_title);prompt=v.findViewById(R.id.text_writing_prompt);tip=v.findViewById(R.id.text_writing_tip);result=v.findViewById(R.id.text_writing_result);reference=v.findViewById(R.id.text_writing_reference);status=v.findViewById(R.id.text_writing_progress);answer=v.findViewById(R.id.edit_writing_answer);v.findViewById(R.id.button_writing_back).setOnClickListener(x->((MainActivity)requireActivity()).openPractice());v.findViewById(R.id.button_writing_check).setOnClickListener(x->check());v.findViewById(R.id.button_writing_next).setOnClickListener(x->{index=(index+1)%items.size();render();});render();return v;}
 private void render(){WritingPrompt p=items.get(index);level.setText(p.level);title.setText(p.title);prompt.setText(p.prompt);tip.setText("提示："+p.tip);status.setText("本地规则检查 · "+(index+1)+" / "+items.size()+" · 写作练习不会上传到网络");answer.setText("");result.setVisibility(View.GONE);reference.setVisibility(View.GONE);}
 private void check(){WritingPrompt p=items.get(index);String text=answer.getText()==null?"":answer.getText().toString().trim();if(text.isEmpty()){Toast.makeText(requireContext(),"先写一点意大利语",Toast.LENGTH_SHORT).show();return;}long start=System.currentTimeMillis();WritingEvaluator.Result r=WritingEvaluator.evaluate(p,text);boolean ok=r.score>=70;progress.recordAuxiliaryResult("writing",ok,System.currentTimeMillis()-start);if(!ok)progress.recordErrorCause(ErrorCause.GRAMMAR,0,"writing",p.id,text,"score="+r.score);result.setText(r.feedback);result.setVisibility(View.VISIBLE);reference.setText("参考表达（不是唯一答案）：\n"+p.reference);reference.setVisibility(View.VISIBLE);}
}
